const streamCache = new Map();
const quickPicksCache = new Map();
let visitorCache = { expiresAt: 0, value: "" };

const MOOD_QUERIES = {
  all: ["Lagu Indonesia Populer Terbaru", "Global Top Hits 2025"],
  pop: ["Pop Indonesia Terbaru Hits", "Lagu Indonesia Viral 2025"],
  galau: ["Lagu Galau Indonesia Terbaru", "Lagu Sedih Indonesia Populer"],
  koplo: ["Lagu Jawa Populer Terbaru", "Musik Koplo Viral Terbaru"],
  chill: ["Indie Indonesia Chill", "Lofi Chill Acoustic"],
  global: ["Global Top Hits 2025", "Top Pop English Songs"],
  remix: ["DJ Remix Viral Terbaru", "Phonk Viral Hits"],
};

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

function parseDurationString(raw) {
  const parts = String(raw || "")
    .trim()
    .split(":")
    .map((p) => Number(p));
  if (parts.some((n) => !Number.isFinite(n))) return 0;
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
}

function extractRuns(column) {
  const runs = column?.musicResponsiveListItemFlexColumnRenderer?.text?.runs;
  if (!Array.isArray(runs)) return [];
  return runs.map((r) => r?.text).filter((t) => typeof t === "string");
}

function upgradeArtwork(url) {
  if (!url) return "";
  return url
    .replace("w60-h60", "w544-h544")
    .replace("w120-h120", "w544-h544")
    .replace("w226-h226", "w544-h544");
}

function parseSongRenderer(renderer) {
  const videoId =
    renderer?.playlistItemData?.videoId ||
    renderer?.overlay?.musicItemThumbnailOverlayRenderer?.content?.musicPlayButtonRenderer
      ?.playNavigationEndpoint?.watchEndpoint?.videoId;

  if (!videoId || typeof videoId !== "string") return null;

  const flexColumns = Array.isArray(renderer.flexColumns) ? renderer.flexColumns : [];
  const title = extractRuns(flexColumns[0]).join("").trim() || "Unknown Track";

  const subRuns = extractRuns(flexColumns[1])
    .map((s) => s.trim())
    .filter((s) => s && s !== "•" && s !== "·" && s !== ",");

  let artist = "Unknown Artist";
  let duration = 0;

  if (subRuns.length > 0) {
    const maybeDuration = parseDurationString(subRuns[subRuns.length - 1]);
    if (maybeDuration > 0) {
      duration = maybeDuration;
      const joined = subRuns.slice(0, -1).join(" ").trim();
      if (joined) artist = joined;
    } else {
      artist = subRuns[0];
    }
  }

  const thumbs = renderer?.thumbnail?.musicThumbnailRenderer?.thumbnail?.thumbnails;
  const rawThumb = Array.isArray(thumbs) && thumbs.length > 0 ? thumbs[thumbs.length - 1]?.url : "";

  return {
    id: videoId,
    title,
    artist,
    thumbnail: upgradeArtwork(rawThumb),
    duration,
  };
}

function collectSongs(node, results, seen) {
  if (!node || typeof node !== "object") return;
  if (Array.isArray(node)) {
    for (const item of node) collectSongs(item, results, seen);
    return;
  }
  if (node.musicResponsiveListItemRenderer) {
    const song = parseSongRenderer(node.musicResponsiveListItemRenderer);
    if (song && !seen.has(song.id)) {
      seen.add(song.id);
      results.push(song);
    }
  }
  for (const val of Object.values(node)) {
    if (val && typeof val === "object") {
      collectSongs(val, results, seen);
    }
  }
}

async function searchSongs(query) {
  const trimmed = String(query || "").trim();
  if (!trimmed) return [];

  const response = await fetch("https://music.youtube.com/youtubei/v1/search?prettyPrint=false", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Origin: "https://music.youtube.com",
      Referer: "https://music.youtube.com/",
      "User-Agent":
        "Mozilla/5.0 (iPhone; CPU iPhone OS 18_3 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.3 Mobile/15E148 Safari/604.1",
    },
    body: JSON.stringify({
      context: {
        client: {
          clientName: "WEB_REMIX",
          clientVersion: "1.20250310.01.00",
          hl: "id",
          gl: "ID",
        },
      },
      query: trimmed,
      params: "EgWKAQIIAWoMEAMQBBAJEAoQBRAV",
    }),
  });

  if (!response.ok) {
    throw new Error("YouTube Music search HTTP " + response.status);
  }

  const json = await response.json();
  const results = [];
  const seen = new Set();
  collectSongs(json, results, seen);
  return results;
}

async function getQuickPicks(mood = "all") {
  const key = MOOD_QUERIES[mood] ? mood : "all";
  const cached = quickPicksCache.get(key);
  if (cached && Date.now() < cached.expiresAt && cached.songs.length > 0) {
    return cached.songs;
  }

  const queries = MOOD_QUERIES[key];
  const settled = await Promise.allSettled(queries.map((q) => searchSongs(q)));
  const combined = [];
  const seen = new Set();

  for (const res of settled) {
    if (res.status === "fulfilled") {
      for (const song of res.value.slice(0, 10)) {
        if (!seen.has(song.id)) {
          seen.add(song.id);
          combined.push(song);
        }
      }
    }
  }

  if (combined.length > 0) {
    quickPicksCache.set(key, { expiresAt: Date.now() + 30 * 60_000, songs: combined });
  }
  return combined;
}

async function getVisitorData() {
  if (visitorCache.value && Date.now() < visitorCache.expiresAt) {
    return visitorCache.value;
  }
  try {
    const res = await fetch("https://music.youtube.com/youtubei/v1/visitor_id?prettyPrint=false", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        context: { client: { clientName: "WEB_REMIX", clientVersion: "1.20250310.01.00" } },
      }),
    });
    if (res.ok) {
      const data = await res.json();
      const v = data?.responseContext?.visitorData;
      if (typeof v === "string" && v.length > 0) {
        visitorCache = { expiresAt: Date.now() + 30 * 60_000, value: v };
        return v;
      }
    }
  } catch {}
  return "";
}

const INNERTUBE_CLIENTS = [
  {
    clientName: "VISIONOS",
    clientVersion: "1.02",
    headerId: "101",
    userAgent:
      "Mozilla/5.0 (Macintosh; Intel Mac OS X 15_7_3) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/26.0 Safari/605.1.15",
    extra: {
      deviceMake: "Apple",
      deviceModel: "RealityDevice17,1",
      osName: "visionOS",
      osVersion: "26.5.23O471",
    },
  },
  {
    clientName: "IOS",
    clientVersion: "20.10.4",
    headerId: "5",
    userAgent: "com.google.ios.youtube/20.10.4 (iPhone16,2; U; CPU iOS 18_3_2 like Mac OS X;)",
    extra: {
      deviceMake: "Apple",
      deviceModel: "iPhone16,2",
      osName: "iOS",
      osVersion: "18.3.2.22D82",
    },
  },
];

async function fetchPlayerForClient(videoId, client, visitorData) {
  const headers = {
    "Content-Type": "application/json",
    "User-Agent": client.userAgent,
    "X-YouTube-Client-Name": client.headerId,
    "X-YouTube-Client-Version": client.clientVersion,
    Origin: "https://www.youtube.com",
  };
  if (visitorData) headers["X-Goog-Visitor-Id"] = visitorData;

  const clientCtx = {
    clientName: client.clientName,
    clientVersion: client.clientVersion,
    hl: "en",
    gl: "US",
    ...client.extra,
  };
  if (visitorData) clientCtx.visitorData = visitorData;

  const response = await fetch("https://www.youtube.com/youtubei/v1/player?prettyPrint=false", {
    method: "POST",
    headers,
    body: JSON.stringify({
      context: { client: clientCtx },
      videoId,
      contentCheckOk: true,
      racyCheckOk: true,
    }),
  });

  if (!response.ok) {
    throw new Error(client.clientName + " HTTP " + response.status);
  }

  const json = await response.json();
  const status = json?.playabilityStatus?.status;
  if (status && status !== "OK") {
    throw new Error(json?.playabilityStatus?.reason || status);
  }

  const adaptive = Array.isArray(json?.streamingData?.adaptiveFormats)
    ? json.streamingData.adaptiveFormats
    : [];
  const muxed = Array.isArray(json?.streamingData?.formats) ? json.streamingData.formats : [];

  for (const itag of [140, 139, 141]) {
    const match = adaptive.find((f) => Number(f?.itag) === itag && typeof f?.url === "string");
    if (match) {
      return {
        url: match.url,
        mimeType: match.mimeType || "audio/mp4",
        userAgent: client.userAgent,
        contentLength: Number(match.contentLength || 0),
      };
    }
  }

  const mp4Audio = adaptive
    .filter((f) => String(f?.mimeType || "").toLowerCase().includes("audio/mp4") && typeof f?.url === "string")
    .sort((a, b) => Number(b?.bitrate || 0) - Number(a?.bitrate || 0));

  if (mp4Audio.length > 0) {
    return {
      url: mp4Audio[0].url,
      mimeType: mp4Audio[0].mimeType || "audio/mp4",
      userAgent: client.userAgent,
      contentLength: Number(mp4Audio[0].contentLength || 0),
    };
  }

  const mp4Muxed = muxed.find(
    (f) => String(f?.mimeType || "").toLowerCase().includes("mp4") && typeof f?.url === "string"
  );
  if (mp4Muxed) {
    return {
      url: mp4Muxed.url,
      mimeType: "audio/mp4",
      userAgent: client.userAgent,
      contentLength: Number(mp4Muxed.contentLength || 0),
    };
  }

  throw new Error(client.clientName + ": no playable MP4/AAC url");
}

async function resolveStream(videoId, forceRefresh = false) {
  if (!forceRefresh) {
    const cached = streamCache.get(videoId);
    if (cached && Date.now() < cached.expiresAt) {
      return cached;
    }
  }

  const visitorData = await getVisitorData();
  let lastError = null;
  for (const client of INNERTUBE_CLIENTS) {
    try {
      const resolved = await fetchPlayerForClient(videoId, client, visitorData);
      const entry = { ...resolved, expiresAt: Date.now() + 20 * 60_000 };
      streamCache.set(videoId, entry);
      return entry;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error("Gagal mendapatkan stream audio");
}

const STREAM_CHUNK_SIZE = 2 * 1024 * 1024;

function parseByteRange(rangeHeader) {
  const m = String(rangeHeader || "").match(/bytes=(\d+)-(\d*)/i);
  if (!m) return { start: 0, reqEnd: null };
  return {
    start: Number(m[1]),
    reqEnd: m[2] ? Number(m[2]) : null,
  };
}

async function handleStreamProxy(request, videoId) {
  if (!/^[a-zA-Z0-9_-]{6,20}$/.test(videoId)) {
    return jsonResponse({ error: "Invalid videoId" }, 400);
  }

  let resolved;
  try {
    resolved = await resolveStream(videoId, false);
  } catch (err) {
    return jsonResponse({ error: err?.message || "Stream resolution failed" }, 502);
  }

  if (request.method === "HEAD") {
    let totalLen = resolved.contentLength || 0;
    if (totalLen <= 0) {
      const probe = await fetch(resolved.url, {
        headers: { "User-Agent": resolved.userAgent, Range: "bytes=0-0" },
      });
      await probe.body?.cancel?.();
      const cr = probe.headers.get("content-range") || "";
      const m = cr.match(/\/(\d+)$/);
      if (m) totalLen = Number(m[1]);
    }
    const headHeaders = new Headers({
      "Content-Type": "audio/mp4",
      "Accept-Ranges": "bytes",
      "Cache-Control": "no-store",
      "Access-Control-Allow-Origin": "*",
    });
    if (totalLen > 0) headHeaders.set("Content-Length", String(totalLen));
    return new Response(null, { status: 200, headers: headHeaders });
  }

  const { start, reqEnd } = parseByteRange(request.headers.get("range"));
  if (resolved.contentLength > 0 && start >= resolved.contentLength) {
    return new Response(null, {
      status: 416,
      headers: {
        "Content-Range": "bytes */" + resolved.contentLength,
        "Access-Control-Allow-Origin": "*",
      },
    });
  }

  const fetchBounded = (target) => {
    let end = reqEnd !== null ? Math.min(reqEnd, start + STREAM_CHUNK_SIZE - 1) : start + STREAM_CHUNK_SIZE - 1;
    if (target.contentLength > 0) {
      end = Math.min(end, target.contentLength - 1);
    }
    const headers = new Headers();
    headers.set("User-Agent", target.userAgent);
    headers.set("Range", "bytes=" + start + "-" + end);
    return fetch(target.url, { method: "GET", headers });
  };

  let upstream = await fetchBounded(resolved);
  if (upstream.status === 403 || upstream.status === 404 || upstream.status === 410) {
    await upstream.body?.cancel?.();
    resolved = await resolveStream(videoId, true);
    upstream = await fetchBounded(resolved);
  }

  if (!upstream.ok && upstream.status !== 206) {
    return jsonResponse({ error: "Upstream audio returned HTTP " + upstream.status }, 502);
  }

  const outHeaders = new Headers();
  outHeaders.set("Content-Type", (upstream.headers.get("content-type") || "audio/mp4").split(";")[0]);
  outHeaders.set("Accept-Ranges", upstream.headers.get("accept-ranges") || "bytes");
  outHeaders.set("Cache-Control", "no-store");
  outHeaders.set("Access-Control-Allow-Origin", "*");

  const contentLength = upstream.headers.get("content-length");
  if (contentLength) outHeaders.set("Content-Length", contentLength);
  const contentRange = upstream.headers.get("content-range");
  if (contentRange) outHeaders.set("Content-Range", contentRange);

  return new Response(upstream.body, {
    status: upstream.status,
    headers: outHeaders,
  });
}

function cleanMetadata(raw) {
  return String(raw || "")
    .replace(/\(feat\.[^)]*\)/gi, "")
    .replace(/\(ft\.[^)]*\)/gi, "")
    .replace(/\[[^\]]*\]/g, "")
    .replace(/\(Official[^)]*\)/gi, "")
    .replace(/\(Lyric[^)]*\)/gi, "")
    .replace(/\(Audio[^)]*\)/gi, "")
    .trim();
}

function parseLrc(lrc) {
  const lines = [];
  const tsRegex = /\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/g;
  for (const rawLine of String(lrc || "").split(/\r?\n/)) {
    const trimmed = rawLine.trim();
    if (!trimmed) continue;
    const matches = [...trimmed.matchAll(tsRegex)];
    if (matches.length === 0) continue;
    const last = matches[matches.length - 1];
    const text = trimmed.slice((last.index || 0) + last[0].length).trim();
    if (!text) continue;
    for (const m of matches) {
      const mins = Number(m[1] || 0);
      const secs = Number(m[2] || 0);
      const frac = String(m[3] || "");
      let ms = 0;
      if (frac.length === 1) ms = Number(frac) * 100;
      else if (frac.length === 2) ms = Number(frac) * 10;
      else if (frac.length >= 3) ms = Number(frac.slice(0, 3));
      lines.push({ timeMs: mins * 60_000 + secs * 1000 + ms, text });
    }
  }
  lines.sort((a, b) => a.timeMs - b.timeMs);
  return lines.map((line, idx) => ({ id: idx, ...line }));
}

function parseLrcRecord(record) {
  if (record?.syncedLyrics && record.syncedLyrics.trim()) {
    const synced = parseLrc(record.syncedLyrics);
    if (synced.length > 0) return synced;
  }
  if (record?.plainLyrics && record.plainLyrics.trim()) {
    return record.plainLyrics
      .split(/\r?\n/)
      .map((s) => s.trim())
      .filter(Boolean)
      .map((text, idx) => ({ id: idx, timeMs: -1, text }));
  }
  return [];
}

async function fetchLyrics(title, artist, duration) {
  const cTitle = cleanMetadata(title);
  const cArtist = cleanMetadata(artist);
  if (!cTitle) return [];

  const headers = { "User-Agent": "WhisMuno-PWA/" + APP_VERSION };
  const exactUrl = new URL("https://lrclib.net/api/get");
  exactUrl.searchParams.set("track_name", cTitle);
  if (cArtist) exactUrl.searchParams.set("artist_name", cArtist);
  if (duration > 10) exactUrl.searchParams.set("duration", String(Math.round(duration)));

  try {
    const r1 = await fetch(exactUrl.toString(), { headers });
    if (r1.ok) {
      const parsed = parseLrcRecord(await r1.json());
      if (parsed.length > 0) return parsed;
    }
  } catch {}

  const searchUrl = new URL("https://lrclib.net/api/search");
  searchUrl.searchParams.set("q", (cTitle + " " + cArtist).trim());
  try {
    const r2 = await fetch(searchUrl.toString(), { headers });
    if (r2.ok) {
      const list = await r2.json();
      if (Array.isArray(list)) {
        for (const item of list) {
          if (item?.syncedLyrics) {
            const parsed = parseLrc(item.syncedLyrics);
            if (parsed.length > 0) return parsed;
          }
        }
        if (list.length > 0) {
          return parseLrcRecord(list[0]);
        }
      }
    }
  } catch {}

  return [];
}

export default {
  async fetch(request) {
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, HEAD, OPTIONS",
          "Access-Control-Allow-Headers": "Range, Content-Type",
        },
      });
    }

    const url = new URL(request.url);
    const pathname = url.pathname;

    try {
      if (pathname === "/health") {
        return jsonResponse({ ok: true, version: APP_VERSION, runtime: "cloudflare-workers" });
      }

      if (pathname === "/api/search") {
        const q = url.searchParams.get("q") || "";
        const songs = await searchSongs(q);
        return jsonResponse({ songs });
      }

      if (pathname === "/api/quick-picks") {
        const mood = url.searchParams.get("mood") || "all";
        const songs = await getQuickPicks(mood);
        return jsonResponse({ songs });
      }

      if (pathname === "/api/lyrics") {
        const title = url.searchParams.get("title") || "";
        const artist = url.searchParams.get("artist") || "";
        const duration = Number(url.searchParams.get("duration") || 0);
        const lines = await fetchLyrics(title, artist, duration);
        return jsonResponse({ lines });
      }

      if (pathname === "/api/stream") {
        const videoId = url.searchParams.get("videoId") || "";
        return await handleStreamProxy(request, videoId);
      }

      if (pathname === "/icon.png") {
        const iconRes = await fetch(ICON_SOURCE_URL, {
          headers: { "User-Agent": "WhisMuno-PWA/2.0.11" },
          cf: { cacheTtl: 86400, cacheEverything: true },
        });
        if (!iconRes.ok) {
          return new Response("Icon unavailable", { status: 404 });
        }
        return new Response(iconRes.body, {
          status: 200,
          headers: {
            "Content-Type": "image/png",
            "Cache-Control": "public, max-age=86400",
          },
        });
      }

      const key = pathname === "/" ? "/index.html" : pathname;
      const asset = ASSETS[key] || ASSETS["/index.html"];
      return new Response(asset.body, {
        status: 200,
        headers: {
          "Content-Type": asset.type,
          "Cache-Control":
            key === "/manifest.webmanifest" ? "public, max-age=3600" : "no-cache",
        },
      });
    } catch (err) {
      return jsonResponse({ error: err?.message || "Internal worker error" }, 500);
    }
  },
};
